/**
 * The data model for generated drawings ("plan sets").
 *
 * A plan set is a handful of sheets (cover, floor plan, enlarged plan, ...).
 * Every sheet is a list of elements drawn from simple shapes. All geometry is
 * in real-world FEET with y pointing down the page (north is up), so lengths
 * and areas are plain arithmetic; the sheet's scale only matters for how big
 * the drawing would be on paper.
 *
 * Drawings are generated by code from a few parameters (see sets.ts). Nothing
 * here is traced or copied from a real architect's drawing.
 */

export type Pt = [number, number];

export type Shape =
  | { t: 'rect'; x: number; y: number; w: number; h: number }
  | { t: 'line'; x1: number; y1: number; x2: number; y2: number }
  | { t: 'poly'; pts: Pt[]; closed?: boolean }
  | { t: 'circle'; cx: number; cy: number; r: number }
  /** A circular arc from angle `from` to `to`, in degrees clockwise from east (screen coordinates). */
  | { t: 'arc'; cx: number; cy: number; r: number; from: number; to: number }
  /** A revision cloud: a scalloped outline around a rectangle. `r` is the radius of each scallop. */
  | { t: 'cloud'; x: number; y: number; w: number; h: number; r: number }
  | { t: 'text'; x: number; y: number; text: string; size: number; anchor?: 'start' | 'middle' | 'end'; bold?: boolean; rot?: number };

/** Line weights, as on a drawn plan: heavy for cut walls, light for everything else. */
/** `phantom` is the long-dash, two-short-dash line used for property lines. */
export type Pen = 'wall' | 'medium' | 'thin' | 'dash' | 'center' | 'phantom' | 'none';
export type Fill = 'none' | 'paper' | 'solid' | 'tint' | 'hatch';

export interface Mark {
  shape: Shape;
  pen: Pen;
  fill?: Fill;
}

export interface PlanElement {
  /** Unique within the sheet, e.g. "unit-203". */
  id: string;
  /** What kind of thing it is, e.g. "unit", "stair", "grid-bubble". Questions match on this or on the id. */
  role: string;
  /** Plain-English name, shown only after grading. */
  name: string;
  marks: Mark[];
  /** The clickable area. Elements without one are drawn but cannot be picked. */
  hit?: Shape;
  /** Clicking jumps to this sheet (callouts, index rows). */
  link?: string;
  /** Floor area in SF, for rooms and units. */
  area?: number;
}

export interface PlanSheet {
  /** The sheet number, e.g. "A-102". */
  id: string;
  title: string;
  /** Discipline designator, e.g. G, C, L, S, A, F, P, M, E. */
  discipline: string;
  scale: {
    /** As written on the drawing, e.g. 1/8" = 1'-0". */
    label: string;
    /** Real feet represented by one inch on paper (8 for 1/8" = 1'-0"; 20 for 1" = 20'). */
    ftPerInch: number;
  };
  /** The paper edge, in feet. */
  bounds: { x: number; y: number; w: number; h: number };
  elements: PlanElement[];
  /** Points the measuring tool snaps to (corners, wall ends, grid intersections). */
  snaps: Pt[];
}

export interface PlanSet {
  id: string;
  title: string;
  /** The parameters this drawing was generated from. */
  params: Record<string, number>;
  sheets: PlanSheet[];
  /**
   * Numbers that can be read or computed from the drawings (lengths in feet,
   * areas in SF, counts). Answer keys are formulas over these names, so they
   * follow the lowercase_with_underscores rule for formula variables.
   */
  facts: Record<string, number>;
}

export interface PlanSetDef {
  id: string;
  title: string;
  /** What the set shows, for builders choosing one. */
  blurb: string;
  /** Default parameters; a question's variant overrides some of them. */
  defaults: Record<string, number>;
  /** Allowed range per parameter, [min, max]. */
  limits: Record<string, [number, number]>;
  build: (params: Record<string, number>) => PlanSet;
}

// ---- geometry helpers ------------------------------------------------------

export function distance(a: Pt, b: Pt): number {
  return Math.hypot(a[0] - b[0], a[1] - b[1]);
}

/** Shoelace area of a polygon. */
export function polygonArea(pts: Pt[]): number {
  let sum = 0;
  for (let i = 0; i < pts.length; i++) {
    const [x1, y1] = pts[i];
    const [x2, y2] = pts[(i + 1) % pts.length];
    sum += x1 * y2 - x2 * y1;
  }
  return Math.abs(sum) / 2;
}

export function shapeArea(s: Shape): number {
  if (s.t === 'rect' || s.t === 'cloud') return s.w * s.h;
  if (s.t === 'poly') return polygonArea(s.pts);
  if (s.t === 'circle') return Math.PI * s.r * s.r;
  return 0;
}

export function shapeContains(s: Shape, p: Pt): boolean {
  if (s.t === 'rect' || s.t === 'cloud') return p[0] >= s.x && p[0] <= s.x + s.w && p[1] >= s.y && p[1] <= s.y + s.h;
  if (s.t === 'circle') return distance([s.cx, s.cy], p) <= s.r;
  if (s.t === 'poly') {
    let inside = false;
    for (let i = 0, j = s.pts.length - 1; i < s.pts.length; j = i++) {
      const [xi, yi] = s.pts[i];
      const [xj, yj] = s.pts[j];
      if (yi > p[1] !== yj > p[1] && p[0] < ((xj - xi) * (p[1] - yi)) / (yj - yi) + xi) inside = !inside;
    }
    return inside;
  }
  return false;
}

export function shapeCentre(s: Shape): Pt {
  if (s.t === 'rect' || s.t === 'cloud') return [s.x + s.w / 2, s.y + s.h / 2];
  if (s.t === 'circle' || s.t === 'arc') return [s.cx, s.cy];
  if (s.t === 'line') return [(s.x1 + s.x2) / 2, (s.y1 + s.y2) / 2];
  if (s.t === 'text') return [s.x, s.y];
  const n = s.pts.length;
  return [s.pts.reduce((a, p) => a + p[0], 0) / n, s.pts.reduce((a, p) => a + p[1], 0) / n];
}

/** 26.5 -> 26'-6" (to the nearest inch). */
export function feetInches(feet: number): string {
  const total = Math.round(Math.abs(feet) * 12);
  const ft = Math.floor(total / 12);
  const inch = total % 12;
  return `${feet < 0 ? '-' : ''}${ft}'-${inch}"`;
}

/** Inches on paper to the nearest 1/16", e.g. 3.25 -> 3 1/4". */
export function paperInches(inches: number): string {
  const sixteenths = Math.round(Math.abs(inches) * 16);
  const whole = Math.floor(sixteenths / 16);
  let num = sixteenths % 16;
  let den = 16;
  while (num > 0 && num % 2 === 0) {
    num /= 2;
    den /= 2;
  }
  if (num === 0) return `${whole}"`;
  return whole > 0 ? `${whole} ${num}/${den}"` : `${num}/${den}"`;
}

/** A question's key matches an element by exact id or by role. */
export function elementMatches(el: PlanElement, key: string): boolean {
  return el.id === key || el.role === key;
}

export function sheetById(set: PlanSet, id: string): PlanSheet | undefined {
  return set.sheets.find((s) => s.id === id);
}
